// Entity Framework (Database First): "Add New Item > ADO.NET Entity Data Model" sihirbazı,
// .edmx diyagramı ve sınıf (DbContext + varlık) üretimi.
import { h, modal, toast } from './ui.js';
import { ensureMysql, sqlCall, mysqlStore } from './mysqlbridge.js';

const HEADER = `//------------------------------------------------------------------------------
// <auto-generated>
//     This code was generated from a template.
//
//     Manual changes to this file may cause unexpected behavior in your application.
//     Manual changes to this file will be overwritten if the code is regenerated.
// </auto-generated>
//------------------------------------------------------------------------------
`;

const CS_KEYWORDS = new Set(['abstract', 'as', 'base', 'bool', 'break', 'byte', 'case', 'catch', 'char', 'checked', 'class', 'const', 'continue', 'decimal', 'default', 'delegate', 'do', 'double', 'else', 'enum', 'event', 'explicit', 'extern', 'false', 'finally', 'fixed', 'float', 'for', 'foreach', 'goto', 'if', 'implicit', 'in', 'int', 'interface', 'internal', 'is', 'lock', 'long', 'namespace', 'new', 'null', 'object', 'operator', 'out', 'override', 'params', 'private', 'protected', 'public', 'readonly', 'ref', 'return', 'sbyte', 'sealed', 'short', 'sizeof', 'stackalloc', 'static', 'string', 'struct', 'switch', 'this', 'throw', 'true', 'try', 'typeof', 'uint', 'ulong', 'unchecked', 'unsafe', 'ushort', 'using', 'virtual', 'void', 'volatile', 'while']);
const ident = (n) => (CS_KEYWORDS.has(n) ? '@' + n : n);

/** MySQL sütun türü → C# türü (EF6 T4 şablonu biçiminde) */
export function clrType(c, pk) {
  const nullable = !c.notNull && !pk;
  let t;
  switch (c.type) {
    case 'int': case 'mediumint': t = c.unsigned ? 'long' : 'int'; break;
    case 'bigint': t = c.unsigned ? 'decimal' : 'long'; break;
    case 'smallint': t = c.unsigned ? 'int' : 'short'; break;
    case 'tinyint': t = c.len === 1 && !c.unsigned ? 'bool' : c.unsigned ? 'byte' : 'sbyte'; break;
    case 'year': t = 'short'; break;
    case 'bit': t = 'bool'; break;
    case 'decimal': t = 'decimal'; break;
    case 'double': t = 'double'; break;
    case 'float': t = 'float'; break;
    case 'date': case 'datetime': case 'timestamp': t = 'System.DateTime'; break;
    case 'time': t = 'System.TimeSpan'; break;
    case 'blob': case 'tinyblob': case 'mediumblob': case 'longblob': case 'binary': case 'varbinary': return 'byte[]';
    default: return 'string';
  }
  return nullable ? `Nullable<${t}>` : t;
}

export function entityName(table, pluralize) {
  return pluralize ? singular(table) : table;
}
export function setName(table, pluralize) {
  return pluralize ? plural(singular(table)) : table;
}
function singular(n) { return /ies$/.test(n) ? n.slice(0, -3) + 'y' : /ses$/.test(n) ? n.slice(0, -2) : /[^s]s$/.test(n) ? n.slice(0, -1) : n; }
function plural(n) { return /[^aeiou]y$/.test(n) ? n.slice(0, -1) + 'ies' : /(s|x|z|ch|sh)$/.test(n) ? n + 'es' : n + 's'; }

/** Modelden üretilen dosyaları (Context, varlık sınıfları, .edmx) oluşturur */
export function generateModel(ide, model) {
  const st = mysqlStore();
  const ctx = st?.server.getDb(model.db);
  if (!ctx) throw new Error(`"${model.db}" veritabanı bulunamadı.`);
  const ns = ide.data.namespace;
  const files = [];
  const entities = [];
  const included = new Set(model.tables.filter((t) => ctx.meta.tables[t]));
  for (const t of included) {
    const m = ctx.meta.tables[t];
    const pk = new Set(m.pk.map((x) => x.toLowerCase()));
    const cls = entityName(m.name, model.pluralize);
    const props = m.columns.filter((c) => model.fk !== false || !m.fks.some((f) => f.cols.some((x) => x.toLowerCase() === c.name.toLowerCase())));
    // gezinme özellikleri: başvurulan tablo (tekil) ve bu tabloya başvuran tablolar (koleksiyon)
    const used = new Set([cls.toLowerCase(), ...props.map((c) => c.name.toLowerCase())]);
    const uniq = (base) => { let n = base; let k = 1; while (used.has(n.toLowerCase())) n = base + k++; used.add(n.toLowerCase()); return n; };
    const refs = m.fks.filter((f) => included.has(f.refTable.toLowerCase())).map((f) => ({ type: entityName(f.refTable.toLowerCase(), model.pluralize), name: uniq(entityName(f.refTable.toLowerCase(), model.pluralize)), fk: f }));
    const colls = [];
    for (const ct of included) {
      for (const f of ctx.meta.tables[ct].fks) {
        if (f.refTable.toLowerCase() !== m.name) continue;
        const ccls = entityName(ct, model.pluralize);
        colls.push({ type: ccls, name: uniq(setName(ct, model.pluralize)), fk: f });
      }
    }
    entities.push({ table: m.name, cls, set: setName(m.name, model.pluralize), meta: m, props, refs, colls });
    const ctor = colls.length ? `        [System.Diagnostics.CodeAnalysis.SuppressMessage("Microsoft.Usage", "CA2214:DoNotCallOverridableMethodsInConstructors")]
        public ${ident(cls)}()
        {
${colls.map((c) => `            this.${ident(c.name)} = new HashSet<${ident(c.type)}>();`).join('\n')}
        }
    
` : '';
    const navLines = [
      ...refs.map((r) => `        public virtual ${ident(r.type)} ${ident(r.name)} { get; set; }`),
      ...colls.map((c) => `        [System.Diagnostics.CodeAnalysis.SuppressMessage("Microsoft.Usage", "CA2227:CollectionPropertiesShouldBeReadOnly")]
        public virtual ICollection<${ident(c.type)}> ${ident(c.name)} { get; set; }`),
    ];
    files.push({
      name: `${cls}.cs`,
      content: `${HEADER}
namespace ${ns}
{
    using System;
    using System.Collections.Generic;
    
    public partial class ${ident(cls)}
    {
${ctor}${props.map((c) => `        public ${clrType(c, pk.has(c.name.toLowerCase()))} ${ident(c.name)} { get; set; }`).join('\n')}
${navLines.length ? '    \n' + navLines.join('\n') + '\n' : ''}    }
}
`,
    });
  }
  files.unshift({
    name: `${model.name}.Context.cs`,
    content: `${HEADER}
namespace ${ns}
{
    using System;
    using System.Data.Entity;
    using System.Data.Entity.Infrastructure;

    public partial class ${model.container} : DbContext
    {
        public ${model.container}()
            : base("name=${model.container}")
        {
        }

        protected override void OnModelCreating(DbModelBuilder modelBuilder)
        {
            throw new UnintentionalCodeFirstException();
        }

${entities.map((e) => `        public virtual DbSet<${ident(e.cls)}> ${ident(e.set)} { get; set; }`).join('\n')}
    }
}
`,
  });
  files.push({ name: `${model.name}.edmx`, content: edmxXml(model, entities) });
  return { files, entities };
}

function storeType(c) {
  if (c.type === 'tinyint' && c.len === 1) return 'bool';
  return c.type === 'integer' ? 'int' : c.type;
}

function csdlType(c, pk) {
  const t = clrType(c, pk).replace(/^Nullable<(.*)>$/, '$1').replace('System.', '');
  return { int: 'Int32', long: 'Int64', short: 'Int16', sbyte: 'SByte', byte: 'Byte', bool: 'Boolean', decimal: 'Decimal', double: 'Double', float: 'Single', DateTime: 'DateTime', TimeSpan: 'Time', 'byte[]': 'Binary', string: 'String' }[t] || 'String';
}

function facets(c, conceptual) {
  let f = '';
  if (['varchar', 'char'].includes(c.type) && c.len) f += ` MaxLength="${c.len}"`;
  if (c.type === 'char' && conceptual) f += ' FixedLength="true"';
  if (['varchar', 'char', 'text', 'tinytext', 'mediumtext', 'longtext', 'enum'].includes(c.type) && conceptual) f += ' Unicode="true"';
  if (c.type === 'decimal') f += ` Precision="${c.len ?? 10}" Scale="${c.scale ?? 0}"`;
  return f;
}

/** Visual Studio'nun ürettiği gibi tam .edmx: SSDL, CSDL, eşleme (MSL) ve ilişkiler */
function edmxXml(model, entities) {
  const x = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  const ns = model.ns;
  const byTable = new Map(entities.map((e) => [e.table, e]));
  // ilişkiler (yalnızca modeldeki tablolar arasında ve FK sütunları modelde ise)
  const assocs = [];
  const independent = model.fk === false; // FK sütunları modelde yok: bağımsız ilişki (AssociationSetMapping)
  {
    for (const e of entities) {
      for (const f of e.meta.fks) {
        const p = byTable.get(f.refTable.toLowerCase());
        if (!p) continue;
        const nullable = f.cols.some((c) => !e.meta.columns.find((x2) => x2.name.toLowerCase() === c.toLowerCase())?.notNull);
        const pr = p.table;
        const dr = e.table === p.table ? e.table + '1' : e.table;
        const ref = e.refs.find((r) => r.fk === f);
        const coll = p.colls.find((cc) => cc.fk === f);
        assocs.push({ name: f.name, principal: p, dependent: e, pr, dr, f, mult: nullable ? '0..1' : '1', ref, coll });
      }
    }
  }
  const ssdl = entities.map((e) => `        <EntityType Name="${x(e.table)}">
          <Key>
${e.meta.pk.map((p) => `            <PropertyRef Name="${x(p)}" />`).join('\n')}
          </Key>
${e.meta.columns.map((c) => `          <Property Name="${x(c.name)}" Type="${x(storeType(c))}"${facets(c, false)} Nullable="${c.notNull || e.meta.pk.includes(c.name) ? 'false' : 'true'}"${c.autoInc ? ' StoreGeneratedPattern="Identity"' : ''} />`).join('\n')}
        </EntityType>`).join('\n');
  const assocXml = (a, conceptual) => `        <Association Name="${x(a.name)}">
          <End Role="${x(a.pr)}" Type="${conceptual ? 'Self.' + x(a.principal.cls) : 'Self.' + x(a.principal.table)}" Multiplicity="${a.mult}" />
          <End Role="${x(a.dr)}" Type="${conceptual ? 'Self.' + x(a.dependent.cls) : 'Self.' + x(a.dependent.table)}" Multiplicity="*" />${conceptual && independent ? '\n        </Association>' : `
          <ReferentialConstraint>
            <Principal Role="${x(a.pr)}">
${a.f.refCols.map((c) => `              <PropertyRef Name="${x(c)}" />`).join('\n')}
            </Principal>
            <Dependent Role="${x(a.dr)}">
${a.f.cols.map((c) => `              <PropertyRef Name="${x(c)}" />`).join('\n')}
            </Dependent>
          </ReferentialConstraint>
        </Association>`}`;
  const csdl = entities.map((e) => `        <EntityType Name="${x(e.cls)}">
          <Key>
${e.meta.pk.map((p) => `            <PropertyRef Name="${x(p)}" />`).join('\n')}
          </Key>
${e.props.map((c) => `          <Property Name="${x(c.name)}" Type="${csdlType(c, e.meta.pk.includes(c.name))}"${facets(c, true)} Nullable="${c.notNull || e.meta.pk.includes(c.name) ? 'false' : 'true'}"${c.autoInc ? ' annotation:StoreGeneratedPattern="Identity"' : ''} />`).join('\n')}
${assocs.filter((a) => a.dependent === e && a.ref).map((a) => `          <NavigationProperty Name="${x(a.ref.name)}" Relationship="Self.${x(a.name)}" FromRole="${x(a.dr)}" ToRole="${x(a.pr)}" />`).join('\n')}
${assocs.filter((a) => a.principal === e && a.coll).map((a) => `          <NavigationProperty Name="${x(a.coll.name)}" Relationship="Self.${x(a.name)}" FromRole="${x(a.pr)}" ToRole="${x(a.dr)}" />`).join('\n')}
        </EntityType>`).join('\n');
  const msl = entities.map((e) => `          <EntitySetMapping Name="${x(e.set)}">
            <EntityTypeMapping TypeName="${x(ns)}.${x(e.cls)}">
              <MappingFragment StoreEntitySet="${x(e.table)}">
${e.props.map((c) => `                <ScalarProperty Name="${x(c.name)}" ColumnName="${x(c.name)}" />`).join('\n')}
              </MappingFragment>
            </EntityTypeMapping>
          </EntitySetMapping>`).join('\n');
  return `<?xml version="1.0" encoding="utf-8"?>
<edmx:Edmx Version="3.0" xmlns:edmx="http://schemas.microsoft.com/ado/2009/11/edmx">
  <!-- EF Runtime content -->
  <edmx:Runtime>
    <!-- SSDL content -->
    <edmx:StorageModels>
      <Schema Namespace="${x(ns)}.Store" Provider="MySql.Data.MySqlClient" ProviderManifestToken="8.0" Alias="Self" xmlns:store="http://schemas.microsoft.com/ado/2007/12/edm/EntityStoreSchemaGenerator" xmlns:customannotation="http://schemas.microsoft.com/ado/2013/11/edm/customannotation" xmlns="http://schemas.microsoft.com/ado/2009/11/edm/ssdl">
${ssdl}
${assocs.map((a) => assocXml(a, false)).join('\n')}
        <EntityContainer Name="${x(ns)}StoreContainer">
${entities.map((e) => `          <EntitySet Name="${x(e.table)}" EntityType="Self.${x(e.table)}" Schema="${x(model.db)}" store:Type="Tables" />`).join('\n')}
${assocs.map((a) => `          <AssociationSet Name="${x(a.name)}" Association="Self.${x(a.name)}">
            <End Role="${x(a.pr)}" EntitySet="${x(a.principal.table)}" />
            <End Role="${x(a.dr)}" EntitySet="${x(a.dependent.table)}" />
          </AssociationSet>`).join('\n')}
        </EntityContainer>
      </Schema>
    </edmx:StorageModels>
    <!-- CSDL content -->
    <edmx:ConceptualModels>
      <Schema Namespace="${x(ns)}" Alias="Self" annotation:UseStrongSpatialTypes="false" xmlns:annotation="http://schemas.microsoft.com/ado/2009/02/edm/annotation" xmlns:customannotation="http://schemas.microsoft.com/ado/2013/11/edm/customannotation" xmlns="http://schemas.microsoft.com/ado/2009/11/edm">
${csdl}
${assocs.map((a) => assocXml(a, true)).join('\n')}
        <EntityContainer Name="${x(model.container)}" annotation:LazyLoadingEnabled="true">
${entities.map((e) => `          <EntitySet Name="${x(e.set)}" EntityType="Self.${x(e.cls)}" />`).join('\n')}
${assocs.map((a) => `          <AssociationSet Name="${x(a.name)}" Association="Self.${x(a.name)}">
            <End Role="${x(a.pr)}" EntitySet="${x(a.principal.set)}" />
            <End Role="${x(a.dr)}" EntitySet="${x(a.dependent.set)}" />
          </AssociationSet>`).join('\n')}
        </EntityContainer>
      </Schema>
    </edmx:ConceptualModels>
    <!-- C-S mapping content -->
    <edmx:Mappings>
      <Mapping Space="C-S" xmlns="http://schemas.microsoft.com/ado/2009/11/mapping/cs">
        <EntityContainerMapping StorageEntityContainer="${x(ns)}StoreContainer" CdmEntityContainer="${x(model.container)}">
${msl}
${independent ? assocs.map((a) => `          <AssociationSetMapping Name="${x(a.name)}" TypeName="${x(ns)}.${x(a.name)}" StoreEntitySet="${x(a.dependent.table)}">
            <EndProperty Name="${x(a.pr)}">
${a.f.refCols.map((c, i) => `              <ScalarProperty Name="${x(c)}" ColumnName="${x(a.f.cols[i])}" />`).join('\n')}
            </EndProperty>
            <EndProperty Name="${x(a.dr)}">
${a.dependent.meta.pk.map((c) => `              <ScalarProperty Name="${x(c)}" ColumnName="${x(c)}" />`).join('\n')}
            </EndProperty>
          </AssociationSetMapping>`).join('\n') : ''}
        </EntityContainerMapping>
      </Mapping>
    </edmx:Mappings>
  </edmx:Runtime>
  <!-- EF Designer content (DO NOT EDIT MANUALLY BELOW HERE) -->
  <Designer xmlns="http://schemas.microsoft.com/ado/2009/11/edmx">
    <Connection>
      <DesignerInfoPropertySet>
        <DesignerProperty Name="MetadataArtifactProcessing" Value="EmbedInOutputAssembly" />
      </DesignerInfoPropertySet>
    </Connection>
    <Options>
      <DesignerInfoPropertySet>
        <DesignerProperty Name="ValidateOnBuild" Value="true" />
        <DesignerProperty Name="EnablePluralization" Value="${model.pluralize ? 'true' : 'false'}" />
        <DesignerProperty Name="IncludeForeignKeysInModel" Value="${model.fk !== false ? 'true' : 'false'}" />
        <DesignerProperty Name="UseLegacyProvider" Value="false" />
        <DesignerProperty Name="CodeGenerationStrategy" Value="None" />
      </DesignerInfoPropertySet>
    </Options>
    <Diagrams></Diagrams>
  </Designer>
</edmx:Edmx>
`;
}

/** App.config içine EF bağlantı cümlesini (ve entityFramework bölümünü) ekler */
export function efAppConfig(existing, model) {
  const conn = `server=${model.conn.server};user id=${model.conn.user};${model.conn.includePassword ? `password=${model.conn.password};` : ''}persistsecurityinfo=True;database=${model.db}`;
  const cs = `metadata=res://*/${model.name}.csdl|res://*/${model.name}.ssdl|res://*/${model.name}.msl;provider=MySql.Data.MySqlClient;provider connection string=&quot;${conn}&quot;`;
  const add = `    <add name="${model.container}" connectionString="${cs}" providerName="System.Data.EntityClient" />`;
  let xml = existing || '<?xml version="1.0" encoding="utf-8"?>\n<configuration>\n</configuration>\n';
  if (!/<configSections>/.test(xml)) {
    xml = xml.replace(/<configuration>/, `<configuration>
  <configSections>
    <section name="entityFramework" type="System.Data.Entity.Internal.ConfigFile.EntityFrameworkSection, EntityFramework, Version=6.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089" requirePermission="false" />
  </configSections>`);
  }
  const re = new RegExp(`\\s*<add name="${model.container}"[^>]*/>`);
  if (re.test(xml)) xml = xml.replace(re, '\n' + add);
  else if (/<connectionStrings>/.test(xml)) xml = xml.replace(/<connectionStrings>/, `<connectionStrings>\n${add}`);
  else xml = xml.replace(/<\/configuration>/, `  <connectionStrings>\n${add}\n  </connectionStrings>\n</configuration>`);
  if (!/<entityFramework>/.test(xml)) {
    xml = xml.replace(/<\/configuration>/, `  <entityFramework>
    <providers>
      <provider invariantName="MySql.Data.MySqlClient" type="MySql.Data.MySqlClient.MySqlProviderServices, MySql.Data.EntityFramework" />
    </providers>
  </entityFramework>
</configuration>`);
  }
  return xml;
}

// ---------------------------------------------------------------- sihirbaz

function card(selected, title, desc, onclick, disabled) {
  return h('div', { class: 'efw-card' + (selected ? ' sel' : '') + (disabled ? ' dis' : ''), onclick: disabled ? null : onclick }, h('div', { class: 'efw-card-ico' }, '⛁'), h('div', {}, h('b', {}, title)), h('div', { class: 'muted small' }, desc));
}

/** Add New Item penceresi */
export async function addNewItem(ide) {
  const items = [
    ['class', 'Class', 'Visual C# Items', 'An empty class definition'],
    ['form', 'Form (Windows Forms)', 'Visual C# Items', 'A blank Windows Form'],
    ['edm', 'ADO.NET Entity Data Model', 'Data', 'A project item for creating an ADO.NET Entity Data Model.'],
    ['config', 'Application Configuration File', 'General', 'A file for storing application configuration and settings information'],
    ['dataset', 'DataSet', 'Data', 'A DataSet for using data in your application (okul.mdf penceresinden)', true],
  ];
  let sel = 'edm';
  const name = h('input', { class: 'input', value: 'Model1' });
  const list = h('div', { class: 'efw-items' });
  const render = () => {
    list.innerHTML = '';
    for (const [id, title, cat, desc, dis] of items) {
      const row = h('div', { class: 'efw-item' + (sel === id ? ' sel' : '') + (dis ? ' dis' : '') }, h('b', {}, title), h('span', { class: 'muted small' }, cat), h('div', { class: 'muted small' }, desc));
      row.onclick = () => {
        if (dis) return;
        sel = id;
        name.value = id === 'edm' ? 'Model1' : id === 'config' ? 'App.config' : id === 'class' ? ide.uniqueFileBase('Class') : ide.uniqueFileBase('Form');
        render();
      };
      list.appendChild(row);
    }
  };
  render();
  const r = await modal({ title: `Add New Item - ${ide.data.namespace}`, width: 640, body: h('div', { class: 'efw' }, list, h('div', { class: 'wb-form-row' }, h('label', {}, 'Name:'), name)), buttons: [{ text: 'Cancel', value: null }, { text: 'Add', value: 'ok', primary: true }] });
  if (r !== 'ok') return;
  const n = name.value.trim();
  if (sel === 'class') ide.addClassDialog(n);
  else if (sel === 'form') ide.addFormDialog(n);
  else if (sel === 'config') ide.addAppConfig();
  else if (sel === 'edm') {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(n)) { toast('Model adı geçerli bir C# adı olmalıdır (ör. SirketModel).', 'error'); return; }
    if (ide.data.files.some((f) => f.name === `${n}.edmx`)) { toast('Bu adda bir model zaten var.', 'error'); return; }
    await entityDataModelWizard(ide, n);
  }
}

async function wizardPage(title, body, { back = true, next = 'Next >', finish = false, validate } = {}) {
  const buttons = [{ text: '< Previous', value: 'back', disabled: !back }, { text: finish ? 'Finish' : next, value: 'next', primary: true, validate }, { text: 'Cancel', value: null }];
  return modal({ title: 'Entity Data Model Wizard', width: 720, body: h('div', { class: 'efw-page' }, h('div', { class: 'efw-title' }, title), body), buttons, dismissable: false });
}

export async function entityDataModelWizard(ide, modelName) {
  let user;
  try { user = ide.ctx.user; await ensureMysql(user); } catch (e) { toast('MySQL simülatörü yüklenemedi: ' + e.message, 'error'); return; }
  const store = mysqlStore();
  const pk = new Set((ide.data.packages || []).map((p) => p.id));
  const connector = store.state.install.products?.includes('connector-net');
  const state = { kind: 'db', conn: ide.data.efConnections?.[0] ? { ...ide.data.efConnections[0] } : null, include: null, save: true, container: '', tables: new Set(), pluralize: false, fk: true, ns: '' };
  let step = 0;
  for (;;) {
    if (step === 0) {
      const box = h('div', { class: 'efw-cards' });
      const draw = () => {
        box.innerHTML = '';
        box.append(card(state.kind === 'db', 'EF Designer from database', 'Creates a model in the EF Designer based on an existing database.', () => { state.kind = 'db'; draw(); }),
          card(state.kind === 'empty', 'Empty EF Designer model', 'Creates an empty model in the EF Designer as a starting point for visually designing your model.', () => { state.kind = 'empty'; draw(); }),
          card(state.kind === 'cf', 'Empty Code First model', 'Creates an empty Code First model as a starting point for designing your model using code.', () => { state.kind = 'cf'; draw(); }),
          card(state.kind === 'cfdb', 'Code First from database', 'Creates a Code First model based on an existing database.', () => { state.kind = 'cfdb'; draw(); }));
      };
      draw();
      const r = await wizardPage('Choose Model Contents', h('div', {}, h('div', {}, 'What should the model contain?'), box), { back: false });
      if (r === null) return;
      if (r === 'next') {
        if (state.kind !== 'db') { toast('Simülatörde yalnızca kitaptaki "EF Designer from database" (Database First) seçeneği desteklenir.', 'info', 5000); continue; }
        step = 1;
      }
      continue;
    }
    if (step === 1) {
      const preview = h('pre', { class: 'efw-cs' });
      const connSel = h('select', { class: 'input' });
      const radios = h('div');
      const saveCb = h('input', { type: 'checkbox', checked: state.save });
      const contIn = h('input', { class: 'input', value: state.container });
      const draw = () => {
        connSel.innerHTML = '';
        if (state.conn) connSel.appendChild(h('option', {}, `${state.conn.server} (${state.conn.database})`));
        else connSel.appendChild(h('option', {}, ''));
        preview.textContent = state.conn ? `metadata=res://*/${modelName}.csdl|res://*/${modelName}.ssdl|res://*/${modelName}.msl;provider=MySql.Data.MySqlClient;provider connection string="server=${state.conn.server};user id=${state.conn.user};${state.include ? 'password=********;' : ''}database=${state.conn.database}"` : '';
        radios.innerHTML = '';
        if (state.conn && state.conn.password) {
          radios.append(h('div', { class: 'small' }, 'This connection string appears to contain sensitive data (for example, a password) that is required to connect to the database. Storing sensitive data in the connection string can be a security risk. Do you want to include this sensitive data in the connection string?'),
            ...[[false, 'No, exclude sensitive data from the connection string. I will set it in my application code.'], [true, 'Yes, include the sensitive data in the connection string.']].map(([v, t]) => {
              const rb = h('input', { type: 'radio', name: 'efsens', checked: state.include === v });
              rb.onchange = () => { state.include = v; draw(); };
              return h('label', { class: 'efw-radio' }, rb, ' ', t);
            }));
        }
        if (!state.container && state.conn) { state.container = `${state.conn.database}Entities`; contIn.value = state.container; }
      };
      contIn.oninput = () => { state.container = contIn.value.trim(); };
      saveCb.onchange = () => { state.save = saveCb.checked; };
      const newConn = h('button', { class: 'btn', onclick: async () => { const c = await newConnection(ide, store, connector, state.conn); if (c) { state.conn = c; state.include = null; state.container = `${c.database}Entities`; contIn.value = state.container; draw(); } } }, 'New Connection...');
      draw();
      const r = await wizardPage('Choose Your Data Connection', h('div', { class: 'efw-col' },
        h('div', {}, 'Which data connection should your application use to connect to the database?'),
        h('div', { class: 'wb-form-row' }, connSel, newConn), radios, h('div', { class: 'muted small' }, 'Connection string:'), preview,
        h('label', { class: 'efw-radio' }, saveCb, ' Save connection settings in App.Config as:'), contIn), {
        validate: () => {
          if (!state.conn) { toast('Önce "New Connection..." ile MySQL bağlantısı oluşturun.', 'error'); return false; }
          if (state.conn.password && state.include === null) { toast('Hassas veri (şifre) seçeneklerinden birini işaretleyin.', 'error'); return false; }
          if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(state.container)) { toast('Bağlantı adı geçerli bir C# adı olmalıdır.', 'error'); return false; }
          return true;
        },
      });
      if (r === null) return;
      step = r === 'back' ? 0 : 2;
      continue;
    }
    if (step === 2) {
      const provider = pk.has('MySql.Data.EntityFramework');
      const r = await wizardPage('Choose Your Version', h('div', { class: 'efw-col' },
        h('div', {}, 'Which version of Entity Framework do you want to use?'),
        h('label', { class: 'efw-radio' + (provider ? '' : ' dis') }, h('input', { type: 'radio', name: 'efv', checked: provider, disabled: !provider }), ' Entity Framework 6.x'),
        h('label', { class: 'efw-radio dis' }, h('input', { type: 'radio', name: 'efv', disabled: true }), ' Entity Framework 5.0'),
        provider ? null : h('div', { class: 'efw-warn' }, '⚠ Your project references the latest version of Entity Framework; however, an Entity Framework database provider compatible with this version could not be found for your data connection. If you have already installed a compatible provider, ensure you have rebuilt your project before performing this action. Otherwise, exit this wizard, install a compatible provider, and rebuild your project before performing this action.'),
        provider ? null : h('div', { class: 'muted small' }, 'İpucu: Proje ▾ > Manage NuGet Packages ile "MySql.Data.EntityFramework" paketini yükleyin (MySql.Data ve EntityFramework paketleri de gelir), sonra sihirbazı yeniden başlatın.')), {
        validate: () => provider,
      });
      if (r === null) return;
      step = r === 'back' ? 1 : 3;
      continue;
    }
    if (step === 3) {
      const ctx = store.server.getDb(state.conn.database);
      const tables = Object.keys(ctx?.meta.tables || {}).sort();
      if (!state.ns) state.ns = `${state.conn.database}Model`;
      const tree = h('div', { class: 'efw-tree' });
      const all = h('input', { type: 'checkbox' });
      const draw = () => {
        tree.innerHTML = '';
        all.checked = tables.length > 0 && tables.every((t) => state.tables.has(t));
        all.indeterminate = state.tables.size > 0 && !all.checked;
        all.onchange = () => { if (all.checked) tables.forEach((t) => state.tables.add(t)); else state.tables.clear(); draw(); };
        tree.append(h('label', { class: 'efw-node' }, all, ' Tables'), h('div', { class: 'efw-node l1' }, '▾ ', state.conn.database),
          ...tables.map((t) => {
            const cb = h('input', { type: 'checkbox', checked: state.tables.has(t) });
            cb.onchange = () => { if (cb.checked) state.tables.add(t); else state.tables.delete(t); draw(); };
            return h('label', { class: 'efw-node l2' }, cb, ' ', t);
          }),
          h('label', { class: 'efw-node' }, h('input', { type: 'checkbox', disabled: true }), ' Views'),
          h('label', { class: 'efw-node' }, h('input', { type: 'checkbox', disabled: true }), ' Stored Procedures and Functions'));
      };
      draw();
      const plur = h('input', { type: 'checkbox', checked: state.pluralize });
      plur.onchange = () => { state.pluralize = plur.checked; };
      const fk = h('input', { type: 'checkbox', checked: state.fk });
      fk.onchange = () => { state.fk = fk.checked; };
      const nsIn = h('input', { class: 'input', value: state.ns });
      nsIn.oninput = () => { state.ns = nsIn.value.trim(); };
      const r = await wizardPage('Choose Your Database Objects and Settings', h('div', { class: 'efw-col' },
        h('div', {}, 'Which database objects do you want to include in your model?'), tree,
        h('label', { class: 'efw-radio' }, plur, ' Pluralize or singularize generated object names'),
        h('label', { class: 'efw-radio' }, fk, ' Include foreign key columns in the model'),
        h('label', { class: 'efw-radio dis' }, h('input', { type: 'checkbox', disabled: true }), ' Import selected stored procedures and functions into the entity model'),
        h('div', { class: 'wb-form-row' }, h('label', {}, 'Model Namespace:'), nsIn)), {
        finish: true,
        validate: () => { if (!state.tables.size) { toast('En az bir tablo seçin.', 'error'); return false; } return true; },
      });
      if (r === null) return;
      if (r === 'back') { step = 2; continue; }
      break;
    }
  }
  // Model oluştur
  const model = { name: modelName, container: state.container, ns: state.ns, db: state.conn.database, tables: [...state.tables], pluralize: state.pluralize, fk: state.fk, conn: { server: state.conn.server, user: state.conn.user, password: state.conn.password, includePassword: !!state.include } };
  ide.data.efConnections = [{ ...state.conn }];
  ide.applyEfModel(model);
  toast(`${modelName}.edmx oluşturuldu. Bağlantı App.config içine "${model.container}" adıyla kaydedildi.`, 'success', 6000);
}

/** Choose Data Source + Connection Properties pencereleri */
async function newConnection(ide, store, connector, prev) {
  const sources = [['mssql', 'Microsoft SQL Server'], ['mdf', 'Microsoft SQL Server Database File'], ...(connector ? [['mysql', 'MySQL Database']] : []), ['other', '<other>']];
  let src = connector ? 'mysql' : 'mssql';
  const list = h('div', { class: 'efw-items' });
  const desc = h('div', { class: 'muted small' });
  const draw = () => {
    list.innerHTML = '';
    for (const [id, t] of sources) {
      const row = h('div', { class: 'efw-item' + (src === id ? ' sel' : '') }, t);
      row.onclick = () => { src = id; draw(); };
      list.appendChild(row);
    }
    desc.textContent = src === 'mysql' ? 'Data provider: .NET Framework Data Provider for MySQL\nUse this selection to connect to MySQL using the MySQL Connector/Net data provider.' : 'Bu veri kaynağı simülatörde kullanılamaz.';
  };
  draw();
  const r = await modal({ title: 'Choose Data Source', width: 560, body: h('div', { class: 'efw-col' }, h('div', {}, 'Data source:'), list, desc,
    connector ? null : h('div', { class: 'efw-warn' }, 'Listede "MySQL Database" yok: Visual Studio\'nun MySQL\'e bağlanabilmesi için Connector/NET ve MySQL for Visual Studio kurulmalıdır. Laboratuvarda MySQL Installer ile "Developer Default" kurulum yapın.')),
  buttons: [{ text: 'Cancel', value: null }, { text: 'Continue', value: 'ok', primary: true }] });
  if (r !== 'ok') return null;
  if (src !== 'mysql') { toast('Simülatörde yalnızca "MySQL Database" veri kaynağı desteklenir.', 'info'); return null; }
  const c = prev ? { ...prev } : { server: 'localhost', user: 'root', password: '', database: '' };
  const srv = h('input', { class: 'input', value: c.server });
  const usr = h('input', { class: 'input', value: c.user });
  const pw = h('input', { class: 'input', type: 'password', value: c.password || '' });
  const savePw = h('input', { type: 'checkbox', checked: true });
  const dbSel = h('select', { class: 'input' });
  const fillDbs = () => {
    dbSel.innerHTML = '';
    for (const d of store.server.databaseNames()) dbSel.appendChild(h('option', { value: d, selected: d === c.database }, d));
  };
  fillDbs();
  const read = () => ({ server: srv.value.trim(), user: usr.value.trim(), password: savePw.checked ? pw.value : '', database: dbSel.value, realPassword: pw.value });
  const test = (silentOk) => {
    const v = read();
    const res = JSON.parse(sqlCall('open', JSON.stringify({ cs: `Server=${v.server};Uid=${v.user};Pwd=${v.realPassword};Database=${v.database}` })));
    if (res.error) { modal({ title: 'MySQL Connector/Net', body: res.error.message, buttons: [{ text: 'OK', value: 'ok', primary: true }] }); return false; }
    sqlCall('close', JSON.stringify({ id: res.id }));
    if (!silentOk) modal({ title: 'Microsoft Visual Studio', body: 'Test connection succeeded.', buttons: [{ text: 'OK', value: 'ok', primary: true }] });
    return true;
  };
  const r2 = await modal({ title: 'Connection Properties', width: 520, body: h('div', { class: 'efw-col' },
    h('div', { class: 'small' }, 'Enter information to connect to the selected data source or click "Change" to choose a different data source and/or provider.'),
    h('div', { class: 'wb-form-row' }, h('label', {}, 'Data source:'), h('b', {}, 'MySQL Database (MySQL Data Provider)')),
    h('div', { class: 'wb-form-row' }, h('label', {}, 'Server name:'), srv), h('div', { class: 'wb-form-row' }, h('label', {}, 'User name:'), usr),
    h('div', { class: 'wb-form-row' }, h('label', {}, 'Password:'), pw), h('label', { class: 'efw-radio' }, savePw, ' Save my password'),
    h('div', { class: 'wb-form-row' }, h('label', {}, 'Database name:'), dbSel),
    h('div', { class: 'wb-form-row' }, h('button', { class: 'btn', onclick: () => test(false) }, 'Test Connection'))),
  buttons: [{ text: 'Cancel', value: null }, { text: 'OK', value: 'ok', primary: true, validate: () => test(true) }] });
  if (r2 !== 'ok') return null;
  const v = read();
  delete v.realPassword;
  return v;
}

/** .edmx diyagramı (Model Browser yerine sade görünüm) */
export function renderEdmx(ide, fileName, container) {
  const model = (ide.data.efModels || []).find((m) => `${m.name}.edmx` === fileName);
  container.innerHTML = '';
  if (!model) { container.appendChild(h('div', { class: 'center-page muted' }, 'Model bilgisi bulunamadı.')); return; }
  const store = mysqlStore();
  const ctx = store?.server.getDb(model.db);
  const canvas = h('div', { class: 'edmx-canvas' });
  let x = 20;
  let y = 20;
  for (const t of model.tables) {
    const m = ctx?.meta.tables[t];
    if (!m) continue;
    const pk = new Set(m.pk.map((p) => p.toLowerCase()));
    const box = h('div', { class: 'edmx-ent', style: { left: x + 'px', top: y + 'px' } },
      h('div', { class: 'edmx-head' }, entityName(m.name, model.pluralize)),
      h('div', { class: 'edmx-sec' }, 'Properties'),
      ...m.columns.map((c) => h('div', { class: 'edmx-prop' }, h('span', {}, pk.has(c.name.toLowerCase()) ? '🔑' : '▪'), ' ', c.name)),
      ...(() => {
        const refs = m.fks.filter((f) => model.tables.includes(f.refTable.toLowerCase())).map((f) => entityName(f.refTable.toLowerCase(), model.pluralize));
        const colls = model.tables.filter((t2) => ctx.meta.tables[t2]?.fks.some((f) => f.refTable.toLowerCase() === m.name)).map((t2) => setName(t2, model.pluralize));
        if (!refs.length && !colls.length) return [];
        return [h('div', { class: 'edmx-sec' }, 'Navigation Properties'), ...refs.map((r) => h('div', { class: 'edmx-prop' }, '↗ ', r)), ...colls.map((c) => h('div', { class: 'edmx-prop' }, '⇉ ', c))];
      })());
    canvas.appendChild(box);
    x += 220;
    if (x > 800) { x = 20; y += 260; }
  }
  container.append(h('div', { class: 'edmx-bar' }, h('b', {}, `${model.name}.edmx [Diagram1]`), h('div', { class: 'spacer' }),
    ide.readonly ? null : h('button', { class: 'btn btn-sm', onclick: async () => {
      try { await ensureMysql(ide.ctx.user); } catch { /* yok */ }
      const db = mysqlStore()?.server.getDb(model.db);
      if (!db) { toast(`"${model.db}" veritabanı bulunamadı.`, 'error'); return; }
      const tables = Object.keys(db.meta.tables).sort();
      const chosen = new Set(model.tables.filter((t) => db.meta.tables[t]));
      const body = h('div', { class: 'efw-col' }, h('div', {}, 'Update Wizard: modele eklenecek ve yenilenecek tablolar'), ...tables.map((t) => { const cb = h('input', { type: 'checkbox', checked: chosen.has(t) }); cb.onchange = () => { if (cb.checked) chosen.add(t); else chosen.delete(t); }; return h('label', { class: 'efw-radio' }, cb, ' ', t); }));
      const r = await modal({ title: 'Update Wizard', body, buttons: [{ text: 'Cancel', value: null }, { text: 'Finish', value: 'ok', primary: true }] });
      if (r !== 'ok') return;
      model.tables = [...chosen];
      ide.applyEfModel(model);
      toast('Model veritabanından güncellendi.', 'success');
    } }, 'Update Model from Database...')), canvas,
  h('div', { class: 'edmx-foot muted small' }, `Bağlantı: ${model.container} (App.config) — Veritabanı: ${model.db}. Sınıflar: ${model.name}.Context.cs ve her tablo için ayrı .cs dosyası.`));
}
